import { Cart, Category, ContactPointEmail, ContactPointPhone, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Checkout step in which the shopper enters their contact information.
*/
export type CheckoutContactInfo = {
    events: Array<Cart | Identity | ContactPointEmail | ContactPointPhone | PartyIdentification | ErrorEvent>;
}

export class CheckoutContactInfoBuilder {

    private checkoutContactInfo: CheckoutContactInfo = {
        events: []
    }

    private cart!: Cart;
    private contactPointEmail!: ContactPointEmail;
    private contactPointPhone!: ContactPointPhone;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : CheckoutContactInfoBuilder {
        this.cart = cart;
        return this;
    }
    public withContactPointEmail(contactPointEmail: ContactPointEmail) : CheckoutContactInfoBuilder {
        this.contactPointEmail = contactPointEmail;
        return this;
    }
    public withContactPointPhone(contactPointPhone: ContactPointPhone) : CheckoutContactInfoBuilder {
        this.contactPointPhone = contactPointPhone;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : CheckoutContactInfoBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : CheckoutContactInfoBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : CheckoutContactInfoBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : CheckoutContactInfo {
        if(this.cart) {
            this.checkoutContactInfo.events.push(this.cart);
        }
        if(this.contactPointEmail) {
            this.checkoutContactInfo.events.push(this.contactPointEmail);
        }
        if(this.contactPointPhone) {
            this.checkoutContactInfo.events.push(this.contactPointPhone);
        }
        if(this.errorEvent) {
            this.checkoutContactInfo.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.checkoutContactInfo.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.checkoutContactInfo.events.push(this.partyIdentification);
        }

        return this.checkoutContactInfo;
    }
}
